// Skeepkaku ("Slicus"): split the board into rectangles, each holding exactly one number equal to
// its area. Drag to draw a rectangle, tap one to erase it. Single-player port of
// Skeepkaku_SceneManager (Input, Board, Feedback), Skeepkaku_BoardView and Skeepkaku_RectView.
// The puzzles are pre-generated by _src/tools/skeepkaku.js (the app's generator, ported).

import { drawPlainBackground } from '../../features/background.js';
import { BoardCelebration } from '../../features/celebration.js';
import { Confetti } from '../../features/confetti.js';
import { theme as appTheme } from '../../theme.js';

// Skeepkaku_Config.asset
const CELL_MAX = 1;               // cellSize (world units)
const BOARD_MAX = 5.8;            // boardMaxSize
const SIDE_MARGIN_UI = 64;        // boardSideMarginUi (canvas units)
const GAP = 0.06;                 // cellGapFraction (of a cell)
const NUMBER = 0.6;               // numberFraction
const DRAG_THRESHOLD = 0.18;      // world units
const HYSTERESIS = 0.2;           // dragCellHysteresis (of a cell)
const FOLLOW_SPEED = 20;          // drawFollowSpeed (exponential, per second)
const OUTLINE_CELL_ALPHA = 0.25;  // cells under an outlined rectangle
const CLUE_CELL_ALPHA = 0.35;
const EMPTY_BLEND = 0.08, FRAME_BLEND = 0.18, NO_CLUE_BLEND = 0.5;
const POP_S = 0.14, POP_SCALE = 0.08;
const CELEBRATE_S = 1.2, RESULT_EXTRA_S = 0.2;
// The shell already waits 0.5 s (SinglePlayerPreResultPresentationDelaySeconds) before the result:
// SolvedCelebrationSeconds = pop + celebration + extra, counted from the solving move.
const CORE_PRE_RESULT_S = 0.5;
const SOLVED_FEEDBACK_CELLS_ABOVE = 0.75;
// The camera fits the scene's 6-unit-wide CameraBounds to the content width.
const BOUNDS_WIDTH = 6;
// The theme's rounded sprites (skeep_rounded.png at 300 px per unit): R8 and R16 corner radii, and
// the frameR8 ring's thickness, in world units.
const R8 = 27 / 300, R16 = 51 / 300, OUTLINE = 0.022;
// Skeepkaku_BoardView: numbers on a filled block go dark above this luminance, white below.
const LIGHT_LUMINANCE = 0.62;
const DARK_NUMBER = '#1a1a1f';
// The theme's feedback tone in dark mode (feedbackText.normalToneDark).
const FEEDBACK_TONE = 2;
const MIN_AREA = 2;
/** Space between the start hint and the top of the board's frame, in canvas units. */
const HINT_GAP = 48;

export default {
  // Skeepkaku_Loc: GAME_TITLE, GAME_DESCRIPTION, GAME_START_HINT, FEEDBACK_COMPLETED; plus
  // SkeepMain's FEEDBACK_GOOD_MOVE_3, the other solved text. GAME_DESCRIPTION_SP is empty.
  text: {
    ca: {
      title: 'Caixa o Faixa',
      description: "Divideix tot el tauler en rectangles. / Cada rectangle té un sol número i ocupa tantes caselles com diu. / Arrossega per dibuixar un rectangle. Toca'l per esborrar-lo.",
      startHint: 'Arrossega per dibuixar rectangles',
      solved: ['Completat!', 'Bona feina!'],
    },
    en: {
      title: 'Slicus',
      description: 'Split the whole board into rectangles. / Each rectangle holds exactly one number and covers that many cells. / Drag to draw a rectangle. Tap it to erase it.',
      startHint: 'Drag to draw rectangles',
      solved: ['Completed!', 'Good job!'],
    },
    es: {
      title: 'Cortus',
      description: 'Divide todo el tablero en rectángulos. / Cada rectángulo tiene un solo número y ocupa tantas casillas como indica. / Arrastra para dibujar un rectángulo. Tócalo para borrarlo.',
      startHint: 'Arrastra para dibujar rectángulos',
      solved: ['¡Completado!', '¡Buen trabajo!'],
    },
  },

  levels: () => fetch(new URL('./levels.json', import.meta.url)).then((r) => {
    if (!r.ok) throw new Error(`levels.json: ${r.status}`);
    return r.json();
  }),

  create: (host) => new Skeepkaku(host),
};

// ── Rules (Skeepkaku_Board) ──

const rect = (row, col, h, w) => ({ row, col, h, w });
const fromCorners = (r0, c0, r1, c1) => rect(Math.min(r0, r1), Math.min(c0, c1), Math.abs(r1 - r0) + 1, Math.abs(c1 - c0) + 1);
const area = (r) => r.h * r.w;
const holds = (r, row, col) => row >= r.row && row < r.row + r.h && col >= r.col && col < r.col + r.w;
const inside = (outer, r) => r.row >= outer.row && r.row + r.h <= outer.row + outer.h && r.col >= outer.col && r.col + r.w <= outer.col + outer.w;
const overlaps = (a, b) => a.row < b.row + b.h && b.row < a.row + a.h && a.col < b.col + b.w && b.col < a.col + a.w;
const union = (a, b) => {
  const row = Math.min(a.row, b.row), col = Math.min(a.col, b.col);
  return rect(row, col, Math.max(a.row + a.h, b.row + b.h) - row, Math.max(a.col + a.w, b.col + b.w) - col);
};
const NO_CLUE = -1, SEVERAL = -2;

class Skeepkaku {
  constructor(host) {
    this.host = host;
    this.placed = [];      // { id, rect, clue, satisfied, view }
    this.dying = [];       // views fading out
    this.nextId = 1;
    this.press = null;
    this.solved = false;
    this.finishIn = -1;
    this.celebration = null;
    this.confetti = new Confetti();
  }

  // ── Lifecycle ──

  load(level) {
    this.rows = level.rows;
    this.cols = level.cols;
    this.clues = level.clues.map(([row, col, value]) => ({ row, col, value }));
    const logic = appTheme.logicColors;
    this.clueColors = level.colors.map((slot) => logic[slot % logic.length]);
    this.preview = newView();
    this.preview.visible = false;
    return Promise.resolve();
  }

  start() {
    // Above the board's frame, so it never covers the numbers.
    this.host.showStartHint(this.host.text.startHint, () => {
      const g = this._geometry();
      return { y: g.top - g.framePad * g.ppu - HINT_GAP * this.host.u, align: 'bottom' };
    });
  }

  pause() { this._cancelPress(); }
  resume() {}
  resize() {}
  destroy() {}

  _evaluate(r) {
    let clue = NO_CLUE;
    for (let i = 0; i < this.clues.length; i++) {
      if (!holds(r, this.clues[i].row, this.clues[i].col)) continue;
      if (clue !== NO_CLUE) return { clue: SEVERAL, satisfied: false };
      clue = i;
    }
    return { clue, satisfied: clue >= 0 && this.clues[clue].value === area(r) };
  }

  _indexAt(row, col) {
    return this.placed.findIndex((p) => holds(p.rect, row, col));
  }

  // ── Input (Skeepkaku_SceneManager.Input) ──

  pointerDown(p) {
    if (this.solved || this.press) return;
    const g = this._geometry();
    const c = this._coords(p, g);
    const row = Math.floor(c.y), col = Math.floor(c.x);
    if (row < 0 || col < 0 || row >= this.rows || col >= this.cols) return;
    this.host.dismissStartHint();
    const index = this._indexAt(row, col);
    this.press = {
      id: p.id, x: p.x, y: p.y, dragging: false,
      startRow: row, startCol: col, row, col,
      base: index >= 0 ? this.placed[index].rect : null,
      baseClue: index >= 0 ? this.placed[index].clue : NO_CLUE,
    };
  }

  pointerMove(p) {
    if (!this.press || this.press.id !== p.id) return;
    this._track(p);
  }

  pointerUp(p) {
    if (!this.press || this.press.id !== p.id) return;
    this._track(p);
    const { dragging, startRow, startCol } = this.press;
    const r = this._dragRect().rect;
    this._cancelPress();
    if (!dragging) this._eraseAt(startRow, startCol);
    else if (area(r) >= MIN_AREA) this._draw(r);
    this.previewHasShape = false;
  }

  _cancelPress() {
    this.press = null;
    this.preview.visible = false;
    this.previewTint = null;
  }

  /** Follows the finger; the rectangle's corner only moves into the next cell once the finger is well inside it. */
  _track(p) {
    const press = this.press;
    const g = this._geometry();
    if (!press.dragging) {
      if (Math.hypot(p.x - press.x, p.y - press.y) < DRAG_THRESHOLD * g.ppu) return;
      press.dragging = true;
    }
    const c = this._coords(p, g);
    press.row = sticky(c.y, press.row, this.rows);
    press.col = sticky(c.x, press.col, this.cols);
    const { rect: r, extending } = this._dragRect();
    if (area(r) < MIN_AREA) {
      this.preview.visible = false;
      this.previewTint = null;
      return;
    }
    const anchor = extending ? press.base : rect(press.startRow, press.startCol, 1, 1);
    if (!this.preview.visible) placeView(this.preview, anchor);
    moveView(this.preview, r);
    const clue = this._evaluate(r).clue;
    this.preview.color = this._colorFor(clue);
    this.preview.fill = 0;
    this.preview.visible = true;
    this.previewHasShape = true;
    this.previewTint = { rect: r, clue };
  }

  /** The gesture's rectangle; if it fits no number, joined with a rectangle it continues in line, if that one does. */
  _dragRect() {
    const chosen = this._chooseDragRect();
    if (area(chosen.rect) < MIN_AREA || this._evaluate(chosen.rect).satisfied) return chosen;
    for (const placed of this.placed) {
      if (inside(placed.rect, chosen.rect) || !touchesInLine(placed.rect, chosen.rect)) continue;
      const joined = union(placed.rect, chosen.rect);
      if (this._evaluate(joined).satisfied) return { rect: joined, extending: chosen.extending };
    }
    return chosen;
  }

  /** From the start cell to the finger, or the rectangle it started in, extended along its line. */
  _chooseDragRect() {
    const p = this.press;
    const drag = fromCorners(p.startRow, p.startCol, p.row, p.col);
    if (!p.base || p.baseClue === SEVERAL || inside(p.base, drag)) return { rect: drag, extending: false };
    if (!continuesInLine(p.base, drag)) return { rect: drag, extending: false };
    const extended = union(p.base, drag);
    const e = this._evaluate(extended);
    if (e.clue !== p.baseClue) return { rect: drag, extending: false };
    if (!e.satisfied && this._evaluate(drag).satisfied) return { rect: drag, extending: false };
    return { rect: extended, extending: true };
  }

  _draw(r) {
    if (r.row < 0 || r.col < 0 || r.row + r.h > this.rows || r.col + r.w > this.cols) return;
    // Rectangles it covers are erased whole.
    for (let i = this.placed.length - 1; i >= 0; i--) {
      if (!overlaps(this.placed[i].rect, r)) continue;
      this._kill(this.placed[i]);
      this.placed.splice(i, 1);
    }
    const { clue, satisfied } = this._evaluate(r);
    const view = newView();
    // It comes out of the preview's current shape, if there was one, and slides to its cells.
    if (this.previewHasShape) {
      Object.assign(view, { cx: this.preview.cx, cy: this.preview.cy, w: this.preview.w, h: this.preview.h });
      moveView(view, r);
    } else {
      placeView(view, r);
    }
    view.color = this._colorFor(clue);
    view.fill = 0;
    view.fillFrom = 0;
    view.fillTo = satisfied ? 1 : 0;
    view.fillT = 0;
    view.pop = 0;
    view.popS = POP_S;
    this.placed.push({ id: this.nextId++, rect: r, clue, satisfied, view });
    if (this.placed.filter((p) => p.satisfied).length === this.clues.length) this._solve();
  }

  _eraseAt(row, col) {
    const i = this._indexAt(row, col);
    if (i < 0) return;
    this._kill(this.placed[i]);
    this.placed.splice(i, 1);
  }

  _kill(placed) {
    placed.view.dyingT = 0;
    this.dying.push(placed.view);
  }

  // ── Solved (Skeepkaku_SceneManager.Board, BoardPuzzleSceneManager.WinSinglePlayer) ──

  _solve() {
    this.solved = true;
    this._cancelPress();
    const g = this._geometry();
    const boardCells = { width: this.cols, height: this.rows };
    this.celebration = new BoardCelebration(boardCells, CELEBRATE_S);
    for (const p of this.placed) {
      const cells = [];
      for (let r = p.rect.row; r < p.rect.row + p.rect.h; r++)
        for (let c = p.rect.col; c < p.rect.col + p.rect.w; c++)
          cells.push({ x: c + 0.5 - this.cols / 2, y: this.rows / 2 - (r + 0.5), id: r * this.cols + c });
      const anchor = { x: p.view.cx - this.cols / 2, y: this.rows / 2 - p.view.cy };
      this.celebration.addBlock(anchor, cells, () => { p.view.pop = 0; p.view.popS = POP_S * 1.5; });
    }
    // The win confetti bursts from the board's top corners and its centre.
    const half = { x: (this.cols * g.cell) / 2, y: (this.rows * g.cell) / 2 };
    this.confetti.play([{ x: -half.x, y: half.y }, { x: 0, y: 0 }, { x: half.x, y: half.y }], this.host.palette.slice(0, 4));
    const texts = this.host.text.solved;
    const [x, y] = g.toPx(0, half.y + g.cell * SOLVED_FEEDBACK_CELLS_ABOVE);
    this.host.feedback(texts[Math.floor(Math.random() * texts.length)], x, y, this.host.palette[FEEDBACK_TONE]);
    this.finishIn = POP_S + CELEBRATE_S + RESULT_EXTRA_S - CORE_PRE_RESULT_S;
  }

  // ── Tick ──

  update(dt) {
    for (const p of this.placed) tickView(p.view, dt);
    tickView(this.preview, dt);
    for (const v of this.dying) tickView(v, dt);
    this.dying = this.dying.filter((v) => v.dyingT < POP_S);
    if (this.celebration) this.celebration.tick(dt);
    this.confetti.tick(dt);
    if (this.finishIn >= 0) {
      this.finishIn -= dt;
      if (this.finishIn < 0) this.host.finish(true);
    }
  }

  // ── Drawing (Skeepkaku_BoardView) ──

  render() {
    const { ctx, width, height, theme } = this.host;
    drawPlainBackground(ctx, width, height, theme);
    const g = this._geometry();
    const surface = theme.surfaceMain, content = theme.contentPrimary;
    const empty = mix(surface, content, EMPTY_BLEND);
    const cellPx = g.cell * g.ppu;
    const side = cellPx * (1 - GAP);
    const r8 = Math.min(R8 * g.ppu, side / 2);

    // Frame, around the cells.
    const pad = g.framePad * g.ppu;
    ctx.fillStyle = mix(surface, content, FRAME_BLEND);
    roundRect(ctx, g.left - pad, g.top - pad, this.cols * cellPx + pad * 2, this.rows * cellPx + pad * 2, R16 * g.ppu);
    ctx.fill();

    // Empty cells, tinted under every rectangle (and under the one being drawn).
    const tint = new Map();
    const paint = (r, color) => {
      for (let row = r.row; row < r.row + r.h; row++)
        for (let col = r.col; col < r.col + r.w; col++) tint.set(row * this.cols + col, mix(empty, color, OUTLINE_CELL_ALPHA));
    };
    for (const p of this.placed) paint(p.rect, this._colorFor(p.clue));
    if (this.previewTint) paint(this.previewTint.rect, this._colorFor(this.previewTint.clue));
    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        ctx.fillStyle = tint.get(row * this.cols + col) || empty;
        roundRect(ctx, g.left + col * cellPx + (cellPx - side) / 2, g.top + row * cellPx + (cellPx - side) / 2, side, side, r8);
        ctx.fill();
      }
    }

    // Each number's cell, faintly in its colour, until its rectangle is complete.
    const satisfied = new Set(this.placed.filter((p) => p.satisfied).map((p) => p.clue));
    this.clues.forEach((c, i) => {
      if (satisfied.has(i)) return;
      ctx.globalAlpha = CLUE_CELL_ALPHA;
      ctx.fillStyle = this.clueColors[i];
      roundRect(ctx, g.left + c.col * cellPx + (cellPx - side) / 2, g.top + c.row * cellPx + (cellPx - side) / 2, side, side, r8);
      ctx.fill();
      ctx.globalAlpha = 1;
    });

    for (const v of this.dying) this._drawView(v, g, r8);
    for (const p of this.placed) this._drawView(p.view, g, r8);
    if (this.preview.visible) this._drawView(this.preview, g, r8);

    // The celebration's white flashes, above the blocks and under the numbers.
    if (this.celebration && this.celebration.running) {
      for (let row = 0; row < this.rows; row++) {
        for (let col = 0; col < this.cols; col++) {
          const a = this.celebration.flashAlpha(row * this.cols + col);
          if (a <= 0) continue;
          ctx.globalAlpha = a;
          ctx.fillStyle = '#ffffff';
          roundRect(ctx, g.left + col * cellPx + (cellPx - side) / 2, g.top + row * cellPx + (cellPx - side) / 2, side, side, r8);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
    }

    // Numbers: the theme's content colour; on a complete block, dark or white by the block's luminance.
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    this.clues.forEach((c, i) => {
      const done = satisfied.has(i);
      ctx.fillStyle = !done ? content : luminance(this.clueColors[i]) > LIGHT_LUMINANCE ? DARK_NUMBER : '#ffffff';
      const text = String(c.value);
      let size = cellPx * NUMBER;
      ctx.font = `700 ${size}px Sora, sans-serif`;
      const w = ctx.measureText(text).width;
      if (w > cellPx * 0.8) size *= (cellPx * 0.8) / w;
      ctx.font = `700 ${size}px Sora, sans-serif`;
      // Sora's figures sit a little high on the middle baseline.
      ctx.fillText(text, g.left + (c.col + 0.5) * cellPx, g.top + (c.row + 0.5) * cellPx + size * 0.04);
    });

    if (this.confetti.playing) this.confetti.draw(ctx, g.toPx, g.ppu);
  }

  /** A rectangle: its fill (opaque when complete) and its outline, both in its number's colour. */
  _drawView(v, g, r8) {
    const { ctx } = this.host;
    const cellPx = g.cell * g.ppu;
    const life = v.dyingT >= 0 ? 1 - Math.min(1, v.dyingT / POP_S) : 1;
    const scale = v.pop >= 0 && v.pop < 1 ? 1 + POP_SCALE * Math.sin(v.pop * Math.PI) : 1;
    const w = v.w * cellPx * scale, h = v.h * cellPx * scale;
    const x = g.left + v.cx * cellPx - w / 2, y = g.top + v.cy * cellPx - h / 2;
    if (v.fill > 0) {
      ctx.globalAlpha = v.fill * life;
      ctx.fillStyle = v.color;
      roundRect(ctx, x, y, w, h, r8);
      ctx.fill();
    }
    const lw = Math.max(1.5, OUTLINE * g.ppu);
    ctx.globalAlpha = life;
    ctx.strokeStyle = v.color;
    ctx.lineWidth = lw;
    roundRect(ctx, x + lw / 2, y + lw / 2, w - lw, h - lw, Math.max(0, r8 - lw / 2));
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  _colorFor(clue) {
    const { theme } = this.host;
    return clue >= 0 ? this.clueColors[clue] : mix(theme.surfaceMain, theme.contentPrimary, NO_CLUE_BLEND);
  }

  /**
   * The board's cell size (Skeepkaku_Config.BoardCellSize): up to 1 world unit, the board within
   * 5.8 × 5.8 and within the screen less the side margins and the frame. Centred in the content area.
   */
  _geometry() {
    const { width, height, insets, u } = this.host;
    const ppu = width / BOUNDS_WIDTH;
    const frameMax = Math.max(0, R16 - R8);
    const maxW = (width - 2 * SIDE_MARGIN_UI * u) / ppu - frameMax * 2;
    const maxH = (height - insets.top - insets.bottom) / ppu - frameMax * 2;
    const cell = Math.min(CELL_MAX, Math.min(BOARD_MAX, maxW) / this.cols, Math.min(BOARD_MAX, maxH) / this.rows);
    const cx = width / 2;
    const cy = insets.top + (height - insets.top - insets.bottom) / 2;
    const left = cx - (this.cols * cell * ppu) / 2;
    const top = cy - (this.rows * cell * ppu) / 2;
    return {
      ppu, cell, left, top,
      framePad: Math.max(0, R16 - R8 - (cell * GAP) / 2),
      toPx: (x, y) => [cx + x * ppu, cy - y * ppu],
    };
  }

  /** Pointer → board coordinates in cells (x = column, y = row, both from the top-left corner). */
  _coords(p, g) {
    const cellPx = g.cell * g.ppu;
    return { x: (p.x - g.left) / cellPx, y: (p.y - g.top) / cellPx };
  }
}

// ── Rectangle views (Skeepkaku_RectView), in cell units ──

function newView() {
  return { cx: 0, cy: 0, w: 0, h: 0, tx: 0, ty: 0, tw: 0, th: 0, following: false, color: '#ffffff', fill: 0, fillFrom: 0, fillTo: 0, fillT: 1, pop: -1, popS: POP_S, dyingT: -1, visible: true };
}

function placeView(v, r) {
  v.cx = v.tx = r.col + r.w / 2;
  v.cy = v.ty = r.row + r.h / 2;
  v.w = v.tw = r.w - GAP;
  v.h = v.th = r.h - GAP;
  v.following = false;
}

function moveView(v, r) {
  v.tx = r.col + r.w / 2;
  v.ty = r.row + r.h / 2;
  v.tw = r.w - GAP;
  v.th = r.h - GAP;
  v.following = true;
}

function tickView(v, dt) {
  if (v.following) {
    const k = 1 - Math.exp(-FOLLOW_SPEED * dt);
    v.cx += (v.tx - v.cx) * k; v.cy += (v.ty - v.cy) * k;
    v.w += (v.tw - v.w) * k; v.h += (v.th - v.h) * k;
  }
  if (v.fillT < 1) {
    v.fillT = Math.min(1, v.fillT + dt / POP_S);
    v.fill = v.fillFrom + (v.fillTo - v.fillFrom) * v.fillT;
  }
  if (v.pop >= 0) {
    v.pop += dt / v.popS;
    if (v.pop >= 1) v.pop = -1;
  }
  if (v.dyingT >= 0) v.dyingT += dt;
}

function sticky(coord, current, count) {
  if (coord >= current - HYSTERESIS && coord < current + 1 + HYSTERESIS) return current;
  return Math.min(count - 1, Math.max(0, Math.floor(coord)));
}

function touchesInLine(r, drag) {
  const horizontal = drag.row === r.row && drag.h === r.h && drag.col <= r.col + r.w && drag.col + drag.w >= r.col;
  const vertical = drag.col === r.col && drag.w === r.w && drag.row <= r.row + r.h && drag.row + drag.h >= r.row;
  return horizontal || vertical;
}

function continuesInLine(r, drag) {
  return (drag.row === r.row && drag.h === r.h) || (drag.col === r.col && drag.w === r.w);
}

function mix(a, b, t) {
  const x = parseInt(a.slice(1), 16), y = parseInt(b.slice(1), 16);
  const ch = (s) => Math.round(((x >> s) & 255) * (1 - t) + ((y >> s) & 255) * t);
  return `#${[16, 8, 0].map((s) => ch(s).toString(16).padStart(2, '0')).join('')}`;
}

function luminance(hex) {
  const n = parseInt(hex.slice(1), 16);
  return (0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255)) / 255;
}

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

